ont-weight:800;line-height:1.25;z-index:1}.nav.open>a,.nav.open .nav-services__summary{min-height:52px!important;border-radius:8px!important;padding:13px 16px!important;font-size:21px!important;border:1px solid transparent!important}.nav.open>a:not(.btn){background:#fff!important;border-color:#EEE1D4!important}.nav.open .btn{margin-top:12px!important;min-height:58px!important;justify-content:center!important;font-size:20px!important;border-radius:10px!important}.burger.open{position:fixed!important;right:22px!important;top:26px!important;z-index:760!important}.nav-backdrop.open{display:none!important}}
