],.page-hero [data-open-modal]{min-height:64px!important;width:100%!important;border-radius:12px!important;justify-content:center!important;background:#FFDD00!important;color:#0D0B08!important;font-size:20px!important;font-weight:900!important}.hero__badges,.hero__stats{max-width:100%!important}}
