        if (strpos($html, 'id="rpd-services-menu-fix"') === false) {
            $html = str_replace('</head>', $styles . "\n</head>", $html);
        }

        $script = <<<'HTML'
<script id="rpd-services-menu-script">
document.querySelectorAll('.nav__item--services').forEach(function(item){var details=item.querySelector('.nav-services');if(!details)return;item.addEventListener('mouseenter',function(){if(window.matchMedia('(min-width: 861px)').matches)details.open=true;});item.addEventListener('mouseleave',function(){if(window.matchMedia('(min-width: 861px)').matches)window.setTimeout(function(){if(!item.matches(':hover'))details.open=false;},220);});});(function(){var path=location.pathname.replace(/\/$/,'');document.querySelectorAll('.nav-services').forEach(function(menu){var summary=menu.querySelector('.nav-services__summary');menu.querySelectorAll('.nav-services__menu a').forEach(function(link){var linkPath=new URL(link.href,location.origin).pathname.replace(/\/$/,'');if(linkPath===path){link.classList.add('is-active');if(summary)summary.classList.add('active');}});});})();
(function(){var logo=document.querySelector('.header .logo');if(logo&&!document.querySelector('.mobile-head-meta')){var meta=document.createElement('div');meta.className='mobile-head-meta';meta.innerHTML='<div class="mobile-head-hours">Ежедневно с 9:00 до 21:00</div><a class="mobile-head-phone" href="tel:+79818345864">+7 (981) 834-58-64</a><button class="mobile-head-call" type="button">Заказать звонок</button><a class="mobile-head-tg" href="https://t.me/rpd_service" target="_blank" rel="noopener">Написать в Telegram</a>';logo.insertAdjacentElement('afterend',meta);var call=meta.querySelector('.mobile-head-call');if(call){call.addEventListener('click',function(e){e.preventDefault();var target=document.querySelector('.header__actions [data-open-modal],.nav .btn[data-open-modal],.page-hero [data-open-modal]');if(target)target.click();});}}document.querySelectorAll('.page-hero.service-hero [data-open-modal],.page-hero.service-hero .btn').forEach(function(btn){if(window.matchMedia('(max-width: 860px)').matches)btn.textContent='Оставить заявку';});})();
(function(){var nav=document.querySelector('.nav');if(nav&&!document.querySelector('.mobile-menu-contact')){var contact=document.createElement('div');contact.className='mobile-menu-contact';contact.innerHTML='<a class="mobile-menu-contact__phone" href="tel:+79818345864">+7 (981) 834-58-64</a><div class="mobile-menu-contact__hours">Ежедневно с 9:00 до 21:00</div><a class="mobile-menu-contact__telegram" href="https://t.me/rpd_service" target="_blank" rel="noopener">Написать в Telegram</a>';nav.appendChild(contact);}})();
